import React, {
    useState,
    useEffect,
    useCallback,
    useRef
} from 'react';

import {
    View,
    FlatList,
} from 'react-native';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';

import { ListItem } from '../../components/ListItem';
import { ListFooter } from '../../components/ListFooter';
import { ListHeader } from '../../components/ListHeader';
import { GetCards } from '../../components/GetCards';

import { styles } from './styles';

import axios from 'axios'

export function RenderList() {
    const { feed } = useContexState();
    const { LoadPage } = useLoadPage();

    const qw = GetCards()

    const [refreshing, setRefreshing] = useState(false);
    const refContainer = useRef<FlatList>(null);

    useEffect(() => {
        LoadPage();
    }, []);

    const [db, setDb] = useState()

    interface typedb {
        data: {
            id: string;
            name: string;
            price: string;
        }[]
    };


    function convertData({ data }: typedb) {
        return data.reduce<any>((h, card) =>
            Object.assign(h, {
                [card.name]: (h[card.name] || [])
                    .concat(
                        {
                            id: card.id,
                            price: card.price,
                        })
            }), {})
    }


    useEffect(() => {
        axios.get("http://18.191.178.251:3000/getCards", {
            params: {
                value: 500
            }
        }).then((responce) => setDb(convertData(responce)));
    }, []);


    const renderItem = useCallback(
        ({ item }) => <ListItem data={item} db={db} />,
        []
    );

    const keyExtractor = useCallback(
        (item) => item.id.toString(),
        []
    );

    function scrollToIndex() {
        if (feed[0]?.lineCards !== 0) {
            refContainer.current?.scrollToIndex({
                index: 0,
                animated: false,
            });
        };
    };

    async function refreshList() {
        setRefreshing(true);
        await LoadPage();
        setRefreshing(false);
    };

    return (
        <View style={styles.listContainer}>
            <FlatList
                viewabilityConfig={{
                    viewAreaCoveragePercentThreshold: 10,
                }}
                ref={refContainer}
                initialNumToRender={10}
                key="list"
                data={feed}
                windowSize={80}
                showsVerticalScrollIndicator={false}
                onRefresh={refreshList}
                refreshing={refreshing}
                renderItem={renderItem}
                keyExtractor={keyExtractor}
                updateCellsBatchingPeriod={50}
                ListHeaderComponent={ListHeader}
                ListFooterComponent={() => {
                    scrollToIndex();
                    return ListFooter();
                }}
            />
        </View>
    );
};
